'use strict';
// READ-ONLY preparation: execute existing payment code against the existing
// transactional test double. This file has no SDK credentials or network I/O.
// Its projected records are fixtures, never current Firestore preimages.
const fs=require('node:fs'),path=require('node:path'),crypto=require('node:crypto'),vm=require('node:vm');
const assert=require('node:assert/strict');
const {createRequire}=require('node:module');
const root=path.resolve(__dirname,'../../integration-v18/repo');
const pins=JSON.parse(fs.readFileSync(path.join(__dirname,'source-pins.json')));
const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const blob=b=>crypto.createHash('sha1').update(Buffer.concat([Buffer.from('blob '+b.length+'\0'),b])).digest('hex');
for(const p of pins.entries){
 const filename=p.path==='orbit360-platform/core/policy-receipts-engine.js'?path.join(__dirname,'policy-receipts-engine.current.js'):path.join(root,p.path);
 assert.equal(blob(fs.readFileSync(filename)),p.gitBlob,'PINNED_CURRENT_OWNER_CHANGED: '+p.path);
}
const harnessPath=path.join(root,'tools/gravicentra-i6-6-source-intake-v2.test.cjs');
const harnessText=fs.readFileSync(harnessPath,'utf8');
const stop=harnessText.indexOf('beforeEach(seed);');
assert.ok(stop>0,'EXISTING_HARNESS_NOT_FOUND');
const sandbox={module:{exports:{}},exports:{},require:createRequire(harnessPath),__dirname:path.dirname(harnessPath),
 __filename:harnessPath,console,process,structuredClone,Buffer};
vm.runInNewContext(harnessText.slice(0,stop)+'\nmodule.exports={seed,command,request,set,item,table,business,documents:()=>documents,writes:()=>writes};',sandbox,{filename:harnessPath});
const h=sandbox.module.exports;
const crosswalk=JSON.parse(fs.readFileSync(path.join(__dirname,'../next56/I6_6_NEW56_FOCAL_ORIGINAL_CROSSWALK_20261124.json')));
const mapfre=crosswalk.mapfre57714;
const policyId=mapfre.policyId,fixtureTenant='synthetic-intake-tenant';
const amount=127.77;
function seed(corrected=true){
 h.seed();
 // Delete only in-memory synthetic financial rows made by the shared fixture.
 for(const key of [...h.documents().keys()])if(['/data/polizas/','/data/recibosEsperados/','/data/carteraPrimas/','/data/cobros/'].some(s=>key.includes(s)))h.documents().delete(key);
 h.set(h.item('polizas',policyId),{id:policyId,tenantId:fixtureTenant,numero:'3002400057714',clienteId:'client_qa',aseguradoraId:'insurer_qa',
  pais:'GT',moneda:'GTQ',vigenciaInicio:'2025-12-23',vigenciaFin:'2026-12-23',estado:'Vigente'});
 for(const row of mapfre.fullIssuedSchedule){
  const paid=row.installment<=9,focus=[10,11].includes(row.installment);
  const premium=focus&&corrected?127.77:127.76;
  h.set(h.item('recibosEsperados',row.receiptId),{id:row.receiptId,tenantId:fixtureTenant,polizaId:policyId,clienteId:'client_qa',aseguradoraId:'insurer_qa',
   pais:'GT',moneda:'GTQ',serie:row.installment+'/12',numeroReciboFuente:focus&&corrected?row.requirement:row.receiptId,
   primaTotal:premium,fechaLimite:focus&&corrected?row.contractualDue:row.beforeDates.fechaLimite,
   ...(paid?{estado:'Pagado',paymentState:'PAID_DIRECT',applicationState:'PENDING_APPLICATION'}:{estado:'Pendiente'})});
  for(const p of row.portfolios)h.set(h.item('carteraPrimas',p.id),{id:p.id,tenantId:fixtureTenant,polizaId:policyId,clienteId:'client_qa',
   reciboId:row.receiptId,pais:'GT',moneda:'GTQ',primaTotal:premium,estado:paid?'Pagado':'Pendiente',carteraActiva:!paid});
  for(const p of row.existingPayments)h.set(h.item('cobros',p.id),{id:p.id,tenantId:fixtureTenant,polizaId:policyId,clienteId:'client_qa',
   reciboId:row.receiptId,pais:'GT',moneda:'GTQ',monto:p.amountCents/100,estado:'Pagado',paymentState:'PAID_DIRECT',applicationState:'PENDING_APPLICATION'});
 }
}
function payload(row){
 const f=row.sourceFact;
 return {receiptId:row.binding.receiptId,sourceType:f.state==='COMMISSION_ANCHOR'?'commission_statement':'insurer_statement',
  amount,paidDate:f.paidDate,actualPaidDateEvidence:true,evidenceId:f.sourceFactId,sourceRef:'drive:'+f.sourceDriveId,
  evidenceType:f.state==='COMMISSION_ANCHOR'?'COMMISSION_STATEMENT_INSTALLMENT_N':'INSURER_CONFIRMED_PAID_STATEMENT',
  evidenceAsOfDate:f.state==='COMMISSION_ANCHOR'?'2026-10-31':'2026-11-22',invoiceNumber:f.invoiceNumber,
  paymentSupportDocumentRef:'drive:'+f.sourceDriveId};
}
function request(row,suffix=''){
 const p=payload(row),req=h.request('apply_payment',p);
 req.data.requestId='mapfre_paid_'+sha(row.sourceFact.sourceRowSha256+'|'+row.binding.receiptId).slice(0,32)+suffix;
 req.data.reason='Fixture condicional de dos pagos documentados; no ejecutado en Firestore.';
 return req;
}
const cases=[];
function note(id,result){cases.push({id,result:'PASS',...result});}
async function main(){
 seed(true);
 const previous=new Map(h.table('cobros').map(([k,v])=>[k,JSON.stringify(v)]));
 for(const row of mapfre.provenPaymentCandidates){
  const out=await h.command.run(request(row));
  assert.equal(out.paymentState,'PAID_DIRECT');assert.equal(out.applicationState,'APPLIED_DIRECT');
  assert.equal(out.paidDate,row.actualPaidDate);assert.equal(out.applicationDate,'');assert.equal(out.invoiceDate,'');
  const receipt=h.documents().get(h.item('recibosEsperados',row.binding.receiptId));
  const payment=h.documents().get(h.item('cobros',out.cobroId));
  assert.equal(payment.monto,amount);assert.equal(receipt.primaTotal,amount);
  assert.equal(payment.directOrInferred,'DIRECT');assert.equal(payment.inferredEffectiveDate,'');
 }
 assert.equal(h.table('cobros').length,11);
 for(const[k,v]of previous)assert.equal(JSON.stringify(h.documents().get(k)),v);
 const created=h.table('cobros').filter(([k])=>!previous.has(k));
 assert.equal(created.reduce((sum,[,v])=>sum+Math.round(v.monto*100),0),25554);
 note('canonical_two_payments_after_hypothetical_correction',{newPayments:2,newPaymentCents:25554,preservedHistoricalPayments:9,
  applicationDateInvented:false,realExecution:false});
 const before=h.writes(),businessBefore=JSON.stringify(h.business());
 for(const row of mapfre.provenPaymentCandidates){const out=await h.command.run(request(row));assert.equal(out.reused,true);}
 assert.equal(h.writes(),before);assert.equal(JSON.stringify(h.business()),businessBefore);
 note('same_request_replay',{newFixtureWrites:0});
 const first=mapfre.provenPaymentCandidates[0];
 const existingCobroId=h.documents().get(h.item('recibosEsperados',first.binding.receiptId)).cobroId;
 const enrichment=await h.command.run(request(first,'_other'));
 assert.equal(enrichment.cobroId,existingCobroId);assert.equal(h.table('cobros').length,11);
 for(const[k,v]of previous)assert.equal(JSON.stringify(h.documents().get(k)),v);
 note('new_insurer_request_enriches_same_payment',{newPayments:0,sameCobroId:true,technicalFixtureWrites:h.writes()-before});
 for(const scenario of ['missing','duplicate']){
  seed(true);const row=mapfre.provenPaymentCandidates[0],portfolio=row.binding.portfolios[0];
  if(scenario==='missing')h.documents().delete(h.item('carteraPrimas',portfolio.id));
  else h.set(h.item('carteraPrimas','duplicate_fixture'),{...h.documents().get(h.item('carteraPrimas',portfolio.id)),id:'duplicate_fixture'});
  await assert.rejects(()=>h.command.run(request(row)));assert.equal(h.writes(),0);
  note(scenario+'_portfolio_blocks',{newFixtureWrites:0});
 }
 // This is a causal limitation, NOT permission to exploit the direct writer:
 // amount override does not itself correct the obligation or bind a CAS digest.
 seed(false);const row=mapfre.provenPaymentCandidates[0];const out=await h.command.run(request(row));
 assert.equal(h.documents().get(h.item('recibosEsperados',row.binding.receiptId)).primaTotal,127.76);
 assert.equal(h.documents().get(h.item('cobros',out.cobroId)).monto,127.77);
 note('uncorrected_amount_override_is_not_a_valid_release_plan',{conditionalPlanStatus:'HOLD_OBLIGATION_CORRECTION_REQUIRED',
  fixtureReceiptCents:12776,fixtureCobroCents:12777,realExecution:false});
 const intake=require(path.join(root,'functions/cobros-source-intake-v2.js'));
 const inference=require(path.join(root,'functions/payment-inference-engine.js'));
 const legacy={numeroReciboFuente:row.binding.receiptId,serie:'10/12'};
 assert.equal(intake.matchesCanonicalInstallment({installment:'10/12'},{},legacy),false);
 assert.equal(inference.receiptSequence(legacy),158);
 note('legacy_parser_remains_separate',{currentIntakeAccepts:false,currentParsedSequence:158});
 const bulk=require(path.join(root,'tools/gravicentra-i66-source-bulk-plan.cjs'));
 const plan=bulk.planSourceBatch(mapfre.provenPaymentCandidates.map(p=>({caseId:p.sourceFact.sourceFactId,insurer:'MAPFRE',policy:'3002400057714',
  requirement:p.sourceFact.requirement,due:p.binding.contractualDue,installment:p.binding.installment,grossCents:12777,state:'PAID',sourceSha256:p.sourceFact.sourceSha256})),[]);
 assert.equal(plan.readyCount,0);assert.equal(plan.exceptions.length,2);
 assert.ok(plan.exceptions.every(p=>p.code==='PAID_REQUIRES_COBRO_PROOF_AND_WRITER'));
 note('pending_bulk_owner_does_not_accept_paid_source',{readyCount:0,exceptions:plan.exceptions});
 return {schema:'GI_I66_MAPFRE57714_CURRENT_OWNER_CONDITIONAL_FIXTURE_V1',status:'LOCAL_CONDITIONAL_SEMANTICS_VERIFIED_REAL_EXECUTION_HOLD',
  sourceHead:pins.sourceHead,fixtureEngine:'existing authenticated domain and existing transactional in-memory harness',
  cases,casesPassed:cases.length,caseFailures:0,remoteWrites:0,livePaymentEligibilityCertified:false,
  fullFinancialPass:false,notProved:['fresh Firestore state','actual deployed callable blob','authentic actor scope','signed preview/live behavior',
   'CAS-protected obligation correction','source proof read by execution service account','complete provider statement identity']};
}
main().then(report=>{fs.writeFileSync(path.join(__dirname,'current-owner-conditional-fixture-result.json'),JSON.stringify(report,null,2)+'\n');
 console.log(JSON.stringify({status:report.status,casesPassed:report.casesPassed,caseFailures:report.caseFailures,remoteWrites:0}));})
 .catch(error=>{console.error(error);process.exitCode=1;});

